package fraymus.workspace;
import org.json.*;
import java.util.*;

/** Extends the original checked pose report with actual alternatives and forecast residuals. */
final class CounterfactualReport045 {
    static JSONObject data(Counterfactual045 store,String study,JSONObject actual)throws Exception{
        store.compareActual(study,actual);var s=store.audit(study);var forecast=store.run(study,s.getJSONObject("decision").getString("selectedCandidate"));
        String body=actual.getJSONObject("plan").getJSONArray("orderedTargets").getJSONObject(0).getString("objectId");
        var rows=new JSONArray();for(Object raw:s.getJSONArray("candidates")){var c=(JSONObject)raw;var m=c.optJSONObject("metrics",new JSONObject());rows.put(new JSONArray(List.of(c.getString("id"),c.getString("status"),m.has("nativeTicks")?String.valueOf(m.getInt("nativeTicks")):"—",m.has("effortNs")?String.format(Locale.ROOT,"%.6f",m.getDouble("effortNs")):"—",m.has("maxBystanderDriftM")?String.format(Locale.ROOT,"%.6f",m.getDouble("maxBystanderDriftM")):"—",c.optString("duplicateOf",c.optString("reason","")))));}
        JSONArray fp=points(forecast,body),ap=points(actual,body);double maxT=Math.max(fp.getJSONArray(fp.length()-1).getDouble(0),ap.getJSONArray(ap.length()-1).getDouble(0)),min=Double.POSITIVE_INFINITY,max=Double.NEGATIVE_INFINITY;
        for(var a:List.of(fp,ap))for(Object raw:a){double x=((JSONArray)raw).getDouble(1);min=Math.min(min,x);max=Math.max(max,x);}
        var charts=new JSONObject().put("bodyId",body).put("xUnit","native simulated seconds").put("yUnit","body X position, metres").put("forecast",project(fp,maxT,min,max)).put("actual",project(ap,maxT,min,max)).put("sourceForecast",fp).put("sourceActual",ap);
        var d=new JSONObject().put("version",Counterfactual045.VERSION).put("scope",Counterfactual045.SCOPE).put("studyId",study).put("binding",s.getJSONObject("binding")).put("sourceFrameSha256",s.getString("sourceFrameSha256")).put("codeSha256",s.getString("codeSha256")).put("decision",s.getJSONObject("decision")).put("decisionSha256",s.getString("decisionSha256")).put("policy",s.getJSONObject("policy")).put("candidates",s.getJSONArray("candidates")).put("rows",rows).put("comparison",s.getJSONObject("comparison")).put("charts",charts);
        return d.put("dataSha256",WorldFrames.hash(d));
    }
    private static JSONArray points(JSONObject run,String body){var out=new JSONArray();for(Object raw:run.getJSONArray("samples")){var s=(JSONObject)raw;out.put(new JSONArray(new double[]{s.getDouble("timeS"),ContactPhysics.dynamic(s.getJSONArray("bodies"),body).getJSONArray("position").getDouble(0)}));}return out;}
    private static JSONArray project(JSONArray points,double time,double min,double max){var out=new JSONArray();for(Object raw:points){var p=(JSONArray)raw;out.put(new JSONArray(new double[]{40+720*p.getDouble(0)/Math.max(.001,time),260-220*(p.getDouble(1)-min)/Math.max(.001,max-min)}));}return out;}
    static JSONArray checks(JSONObject d){return new JSONArray().put(new JSONObject().put("selector","#cf045-status").put("expectText","Forecast and execution verified")).put(new JSONObject().put("selector","#cf045-candidates tbody tr").put("expectCount",d.getJSONArray("rows").length())).put(new JSONObject().put("selector","#cf045-selected").put("expectText",d.getJSONObject("decision").getString("selectedCandidate"))).put(new JSONObject().put("selector","#cf045-head").put("expectText",d.getJSONObject("binding").getString("expectedHash"))).put(new JSONObject().put("selector","#cf045-hash").put("expectText",d.getString("dataSha256"))).put(new JSONObject().put("selector","#cf045-forecast").put("expectCount",1)).put(new JSONObject().put("selector","#cf045-actual").put("expectCount",1));}
    static JSONObject verifyView(JSONObject d,JSONObject view){if(!view.getBoolean("visible")||!view.getJSONObject("data").similar(d)||!view.getJSONArray("rows").similar(d.getJSONArray("rows")))throw new IllegalStateException("Counterfactual source/table view differs from original evidence");double error=0;int count=0;for(String key:List.of("forecast","actual")){JSONArray p=d.getJSONObject("charts").getJSONArray(key),observed=view.getJSONArray(key);if(p.length()!=observed.length())throw new IllegalStateException("Missing forecast/actual chart samples");for(int i=0;i<p.length();i++){if(observed.getJSONArray(i).length()!=2)throw new IllegalStateException("Invalid counterfactual chart point");for(int n=0;n<2;n++){double e=Math.abs(p.getJSONArray(i).getDouble(n)-observed.getJSONArray(i).getDouble(n));if(!Double.isFinite(e))throw new IllegalStateException("Nonfinite chart point");error=Math.max(error,e);}count++;}}if(error>.002)throw new IllegalStateException("Rendered forecast/actual chart differs");return new JSONObject().put("passed",true).put("dataSha256",d.getString("dataSha256")).put("points",count).put("maxError",error);}
    static JSONObject build(JSONObject actual,JSONObject data,JSONArray attempts){var out=WorldReport.build(actual);out.put("title","Counterfactual world · "+actual.getJSONObject("definition").getString("title"));var files=out.getJSONObject("files");files.put("index.html",files.getString("index.html").replace("</main>",HTML+"</main>"));files.put("counterfactual.json",data.toString());var manifest=new JSONArray();for(int i=0;i<attempts.length();i++){String name="forecast-attempt-"+(i+1)+".json";var a=attempts.getJSONObject(i);files.put(name,a.toString());manifest.put(new JSONObject().put("file",name).put("candidate",a.getString("candidate")).put("status",a.getString("status")).put("rawSha256",a.getJSONObject("run").getString("rawSha256")));}files.put("forecast-files.json",manifest.toString());out.getJSONArray("sources").put("counterfactual-decision:"+data.getString("decisionSha256"));return out;}
    private static final String HTML="""
<section id="cf045-section"><h2 id="cf045-status">Loading original alternatives…</h2><p>Three declared alternatives begin from the same saved world frame. Failed trials remain visible. Forecasts use the same native solver as execution; this is a deterministic simulation comparison.</p><p>Chosen: <b id="cf045-selected"></b></p><p>Original world head: <span id="cf045-head"></span></p><div class="table"><table id="cf045-candidates"><thead><tr><th>Alternative</th><th>Outcome</th><th>Native ticks</th><th>Effort N·s</th><th>Protected drift m</th><th>Reason / duplicate</th></tr></thead><tbody></tbody></table></div><h3>Predicted versus actual motion</h3><p>Forecast: dashed amber. Actual: solid mint. Overlap means the two original traces agree.</p><svg viewBox="0 0 800 300" aria-label="Predicted and actual body motion"><path d="M40 20V260H760" stroke="#5a786e" fill="none"/><polyline id="cf045-forecast" stroke="#d68d25" stroke-width="5" stroke-dasharray="8 6" fill="none"/><polyline id="cf045-actual" stroke="#237c5b" stroke-width="2" fill="none"/></svg><p id="cf045-residual"></p><p>Evidence hash: <span id="cf045-hash"></span></p><details><summary>Original alternatives and comparison</summary><pre id="cf045-data"></pre></details><p><a href="counterfactual.json" download>Numeric comparison JSON</a> · <a href="forecast-files.json" download>Lossless forecast file manifest</a></p><ul id="cf045-downloads"></ul></section><script>
(async()=>{const d=await(await fetch('counterfactual.json')).json(),$=id=>document.getElementById(id);$('cf045-selected').textContent=d.decision.selectedCandidate;$('cf045-head').textContent=d.binding.expectedHash;$('cf045-hash').textContent=d.dataSha256;for(const row of d.rows){const tr=document.createElement('tr');for(const x of row){const td=document.createElement('td');td.textContent=x;tr.append(td);}$('cf045-candidates').tBodies[0].append(tr);}for(const k of ['forecast','actual'])$('cf045-'+k).setAttribute('points',d.charts[k].map(p=>p.join(',')).join(' '));$('cf045-residual').textContent=d.charts.xUnit+' / '+d.charts.yUnit+' · maximum residual '+d.comparison.maxPositionResidualM.toFixed(8)+'m · '+d.comparison.maxAngleResidualDeg.toFixed(8)+'deg · coverage '+d.comparison.sampleCoverage;$('cf045-data').textContent=JSON.stringify(d,null,2);for(const f of await(await fetch('forecast-files.json')).json()){const li=document.createElement('li'),a=document.createElement('a');a.href=f.file;a.download=f.file;a.textContent=f.candidate+' · '+f.status+' · original compressed trace';li.append(a);$('cf045-downloads').append(li);}$('cf045-status').textContent=d.comparison.passed?'Forecast and execution verified':'Forecast comparison failed';})().catch(e=>{document.querySelector('#cf045-status').textContent='Counterfactual evidence failed: '+e.message;throw e;});
</script>
""";
}
